def daily_temperatures(temps):
    answer = [0] * len(temps)
    waiting = []                                   # days still waiting for a warmer day; their temperatures never rise towards the top
    for today, temp in enumerate(temps):
        while waiting and temps[waiting[-1]] < temp:
            colder_day = waiting.pop()
            answer[colder_day] = today - colder_day
        waiting.append(today)
    return answer
